import pickle
import hashlib
from typing import Any, Optional
import time

class SessionCache:
    def __init__(self, ttl_seconds: int = 3600):
        self.cache = {}
        self.ttl = ttl_seconds
        self.timestamps = {}

    def get(self, session_id: str) -> Optional[Any]:
        if session_id not in self.cache:
            return None
        if time.time() - self.timestamps[session_id] > self.ttl:
            del self.cache[session_id]
            del self.timestamps[session_id]
            return None
        return pickle.loads(self.cache[session_id])

    def set(self, session_id: str, session_data: dict) -> None:
        # Serialize directly without validation for maximum speed
        self.cache[session_id] = pickle.dumps(session_data)
        self.timestamps[session_id] = time.time()

    def invalidate(self, session_id: str) -> None:
        if session_id in self.cache:
            del self.cache[session_id]
            del self.timestamps[session_id]

# Usage
cache = SessionCache()
cache.set('user_123', {'user_id': 123, 'role': 'admin', 'permissions': ['read', 'write']})
user_data = cache.get('user_123')
